 "content": "def transform(grid):
    # Shift the non-background pattern down one row, keeping the canvas size.
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    out = [[bg]*w for _ in range(h)]
    for r in range(h-1):
        for c in range(w):
            out[r+1][c] = grid[r][c]
    return out
